                                                            <div class="platform-content container"><div class="row"><div class="col"><div class="com-content-article""><div class="pdf-print-icon"><a class="btn btn-danger" href="/vospitanie/dlya-roditelej/16-vazhnykh-pravil-pro-eto?tmpl=component&amp;format=pdf" onclick="window.open(this.href,'win2','status=no,toolbar=no,scrollbars=yes,titlebar=no,menubar=no,resizable=yes,width=640,height=480,directories=no,location=no'); return false;" target=""><span class="glyphicon glyphicon-file icon-file"></span> PDF</a></div>
